import { Navigate, useLocation } from 'react-router-dom'
import type { ReactNode } from 'react'
import { useAuth } from '../store/AuthContext'

/**
 * 整页登录守卫（备好供里程碑 4「我的收藏」等页面使用）。
 * 本阶段点赞/收藏按钮采用「点击时判断」而非整页守卫，故暂无路由挂载。
 */
export default function RequireAuth({ children }: { children: ReactNode }) {
  const { user, ready } = useAuth()
  const location = useLocation()

  if (!ready) {
    return null
  }
  if (!user) {
    const from = encodeURIComponent(location.pathname + location.search)
    return <Navigate to={`/login?from=${from}`} replace />
  }
  return children
}

package com.shortdrama.api.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

/**
 * 将上传目录映射为静态资源 /uploads/**。
 * 相对路径基于后端进程工作目录（apps/api），阶段1 的 StorageService 落盘与读取同源于此。
 */
@Configuration
public class WebMvcConfig implements WebMvcConfigurer {

    private final String uploadDir;

    public WebMvcConfig(@Value("${app.upload-dir}") String uploadDir) {
        this.uploadDir = uploadDir;
    }

    @Override
    public void addResourceHandlers(ResourceHandlerRegistry registry) {
        registry.addResourceHandler("/uploads/**")
                .addResourceLocations("file:" + (uploadDir.endsWith("/") ? uploadDir : uploadDir + "/"));
    }
}
package com.shortdrama.api.security;

import com.shortdrama.api.entity.UserRole;
import org.springframework.security.core.GrantedAuthority;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.userdetails.UserDetails;

import java.util.Collection;
import java.util.List;

/**
 * SecurityContext 中的当前登录用户，供 @AuthenticationPrincipal 注入。
 * 两条构造路径：JWT 过滤器（无密码摘要）/ UserDetailsService（带 BCrypt 摘要供登录校验）。
 */
public class AuthUser implements UserDetails {

    private final Long id;
    private final String username;
    /** BCrypt 摘要；来自 token 构造时为空串。 */
    private final String password;
    private final UserRole role;

    public AuthUser(Long id, String username, String password, UserRole role) {
        this.id = id;
        this.username = username;
        this.password = password;
        this.role = role;
    }

    public Long getId() {
        return id;
    }

    public UserRole getRole() {
        return role;
    }

    @Override
    public Collection<? extends GrantedAuthority> getAuthorities() {
        return List.of(new SimpleGrantedAuthority("ROLE_" + role.name()));
    }

    @Override
    public String getPassword() {
        return password;
    }

    @Override
    public String getUsername() {
        return username;
    }
}
